package com.nbi.profile.model;

// Stored as JSON string for simplicity so JSON Patch can be applied directly.
public class Profile {
    private String id;
    private String json; // the current JSON representation

    public Profile(String id, String json) { this.id = id; this.json = json; }
    public String getId() { return id; }
    public String getJson() { return json; }
    public void setJson(String json) { this.json = json; }
}
