// ─── File: src/main/java/com/nbi/profile/service/ProfileService.java ───
package com.nbi.profile.service;

import com.nbi.profile.model.Profile;
import org.springframework.stereotype.Service;
import jakarta.json.*;
import java.io.StringReader;
import java.util.*;

@Service
public class ProfileService {
    private final Map<String, Profile> store = new HashMap<>();

    public ProfileService() {
        store.put("CUR3001", new Profile("CUR3001",
            "{\"nickname\":\"Rajesh\",\"ifsc\":\"NBI0001234\",\"nominees\":[]}"));
    }

    public Optional<Profile> find(String id) { return Optional.ofNullable(store.get(id)); }

    // Apply an RFC 6902 JSON Patch atomically. Any failing op (incl. test) aborts all.
    public Optional<String> applyPatch(String id, String patchJson) {
        Profile p = store.get(id);
        if (p == null) return Optional.empty();

        JsonArray patchArray = Json.createReader(new StringReader(patchJson)).readArray();
        JsonPatch patch = Json.createPatchBuilder(patchArray).build();
        JsonObject target = Json.createReader(new StringReader(p.getJson())).readObject();

        // apply() throws JsonException if a test fails or a path is invalid → nothing saved.
        JsonObject patched = patch.apply(target);
        p.setJson(patched.toString());
        return Optional.of(p.getJson());
    }
}
```

```java
// ─── File: src/main/java/com/nbi/profile/controller/ProfileController.java ───
package com.nbi.profile.controller;

import com.nbi.profile.service.ProfileService;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import jakarta.json.JsonException;

@RestController
@RequestMapping("/api/v1/profiles")
public class ProfileController {

    private final ProfileService service;
    public ProfileController(ProfileService service) { this.service = service; }

    // PATCH with JSON Patch media type. Body is an array of operations.
    @PatchMapping(value = "/{id}", consumes = "application/json-patch+json")
    public ResponseEntity<String> patch(@PathVariable String id, @RequestBody String patchJson) {
        try {
            return service.applyPatch(id, patchJson)
                    .map(ResponseEntity::ok)
                    .orElse(ResponseEntity.notFound().build());
        } catch (JsonException e) {
            // A failing 'test' op or bad path → 409 Conflict / 422, nothing changed.
            return ResponseEntity.status(HttpStatus.CONFLICT)
                    .body("{\"error\":\"patch failed: " + e.getMessage() + "\"}");
        }
    }
}
